package com.rightclickstyler;

import java.awt.Color;
import java.util.Objects;

/**
 * An immutable, fully self-contained menu style: colours, geometry style and visibility toggles.
 * Built-in themes are locked (never edited or deleted); user themes are editable and saved to config.
 */
final class Theme
{
	final String id;
	final String name;
	final boolean builtIn;
	final Color bg;
	final Color border;
	final Color header;
	final Color headerText;
	final Color text;
	final Color hover;
	final Color accent;
	final int radius;
	final int opacity;
	final HoverStyle hoverStyle;
	final boolean showBorder;
	final boolean showShadow;
	final boolean showHeader;
	final FontChoice font;
	final int fontSize;
	final boolean textShadow;

	Theme(String id, String name, boolean builtIn, Color bg, Color border, Color header, Color headerText,
		Color text, Color hover, Color accent, int radius, int opacity, HoverStyle hoverStyle,
		boolean showBorder, boolean showShadow, boolean showHeader, FontChoice font, int fontSize,
		boolean textShadow)
	{
		this.id = id;
		this.name = name;
		this.builtIn = builtIn;
		this.bg = bg;
		this.border = border;
		this.header = header;
		this.headerText = headerText;
		this.text = text;
		this.hover = hover;
		this.accent = accent;
		this.radius = radius;
		this.opacity = opacity;
		this.hoverStyle = hoverStyle;
		this.showBorder = showBorder;
		this.showShadow = showShadow;
		this.showHeader = showHeader;
		this.font = font;
		this.fontSize = fontSize;
		this.textShadow = textShadow;
	}

	Theme withIdentity(String id, String name, boolean builtIn)
	{
		return new Theme(id, name, builtIn, bg, border, header, headerText, text, hover, accent,
			radius, opacity, hoverStyle, showBorder, showShadow, showHeader, font, fontSize, textShadow);
	}

	Theme withBg(Color v)
	{
		return new Theme(id, name, builtIn, v, border, header, headerText, text, hover, accent,
			radius, opacity, hoverStyle, showBorder, showShadow, showHeader, font, fontSize, textShadow);
	}

	Theme withBorder(Color v)
	{
		return new Theme(id, name, builtIn, bg, v, header, headerText, text, hover, accent,
			radius, opacity, hoverStyle, showBorder, showShadow, showHeader, font, fontSize, textShadow);
	}

	Theme withHeader(Color v)
	{
		return new Theme(id, name, builtIn, bg, border, v, headerText, text, hover, accent,
			radius, opacity, hoverStyle, showBorder, showShadow, showHeader, font, fontSize, textShadow);
	}

	Theme withHeaderText(Color v)
	{
		return new Theme(id, name, builtIn, bg, border, header, v, text, hover, accent,
			radius, opacity, hoverStyle, showBorder, showShadow, showHeader, font, fontSize, textShadow);
	}

	Theme withText(Color v)
	{
		return new Theme(id, name, builtIn, bg, border, header, headerText, v, hover, accent,
			radius, opacity, hoverStyle, showBorder, showShadow, showHeader, font, fontSize, textShadow);
	}

	Theme withHover(Color v)
	{
		return new Theme(id, name, builtIn, bg, border, header, headerText, text, v, accent,
			radius, opacity, hoverStyle, showBorder, showShadow, showHeader, font, fontSize, textShadow);
	}

	Theme withAccent(Color v)
	{
		return new Theme(id, name, builtIn, bg, border, header, headerText, text, hover, v,
			radius, opacity, hoverStyle, showBorder, showShadow, showHeader, font, fontSize, textShadow);
	}

	Theme withRadius(int v)
	{
		return new Theme(id, name, builtIn, bg, border, header, headerText, text, hover, accent,
			v, opacity, hoverStyle, showBorder, showShadow, showHeader, font, fontSize, textShadow);
	}

	Theme withOpacity(int v)
	{
		return new Theme(id, name, builtIn, bg, border, header, headerText, text, hover, accent,
			radius, v, hoverStyle, showBorder, showShadow, showHeader, font, fontSize, textShadow);
	}

	Theme withHoverStyle(HoverStyle v)
	{
		return new Theme(id, name, builtIn, bg, border, header, headerText, text, hover, accent,
			radius, opacity, v, showBorder, showShadow, showHeader, font, fontSize, textShadow);
	}

	Theme withShowBorder(boolean v)
	{
		return new Theme(id, name, builtIn, bg, border, header, headerText, text, hover, accent,
			radius, opacity, hoverStyle, v, showShadow, showHeader, font, fontSize, textShadow);
	}

	Theme withShowShadow(boolean v)
	{
		return new Theme(id, name, builtIn, bg, border, header, headerText, text, hover, accent,
			radius, opacity, hoverStyle, showBorder, v, showHeader, font, fontSize, textShadow);
	}

	Theme withShowHeader(boolean v)
	{
		return new Theme(id, name, builtIn, bg, border, header, headerText, text, hover, accent,
			radius, opacity, hoverStyle, showBorder, showShadow, v, font, fontSize, textShadow);
	}

	Theme withFont(FontChoice v)
	{
		return new Theme(id, name, builtIn, bg, border, header, headerText, text, hover, accent,
			radius, opacity, hoverStyle, showBorder, showShadow, showHeader, v, fontSize, textShadow);
	}

	Theme withFontSize(int v)
	{
		return new Theme(id, name, builtIn, bg, border, header, headerText, text, hover, accent,
			radius, opacity, hoverStyle, showBorder, showShadow, showHeader, font, v, textShadow);
	}

	Theme withTextShadow(boolean v)
	{
		return new Theme(id, name, builtIn, bg, border, header, headerText, text, hover, accent,
			radius, opacity, hoverStyle, showBorder, showShadow, showHeader, font, fontSize, v);
	}

	/**
	 * True if every visual field matches, ignoring identity (id, name, builtIn). Drives the "edited"
	 * state, so it must cover every style field.
	 */
	boolean sameStyle(Theme o)
	{
		return bg.equals(o.bg) && border.equals(o.border) && header.equals(o.header)
			&& headerText.equals(o.headerText) && text.equals(o.text) && hover.equals(o.hover)
			&& accent.equals(o.accent) && radius == o.radius && opacity == o.opacity
			&& hoverStyle == o.hoverStyle && showBorder == o.showBorder && showShadow == o.showShadow
			&& showHeader == o.showHeader && font == o.font && fontSize == o.fontSize
			&& textShadow == o.textShadow;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof Theme))
		{
			return false;
		}
		Theme t = (Theme) o;
		return id.equals(t.id) && name.equals(t.name) && builtIn == t.builtIn && sameStyle(t);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(id, name, builtIn, bg, border, header, headerText, text, hover, accent,
			radius, opacity, hoverStyle, showBorder, showShadow, showHeader, font, fontSize, textShadow);
	}
}

package com.rightclickstyler;

import com.google.gson.Gson;
import java.awt.Color;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.function.BiConsumer;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Owns the built-in and user themes, which theme is active, and the "working copy" that the overlay
 * and the sidebar preview both render live as the user edits. User themes are saved as JSON in
 * the {@code userThemes} config key and hidden {@code activeTheme} config item.
 * <p>
 * After startup, everything except {@link #effectiveTheme()} is only touched from the EDT (the
 * panel). The overlay reads {@link #effectiveTheme()} on the client thread; {@link Theme} is
 * immutable and the reference is volatile, so it always sees a complete theme.
 */
@Slf4j
@Singleton
class ThemeManager
{
	private static final String EXPORT_PREFIX = "rightclickstyler:";
	private static final String DEFAULT_THEME_NAME = "Theme";
	private static final String COPY_SUFFIX = " copy";

	static final String ERROR_FULL = "You already have the maximum of " + Limits.MAX_USER_THEMES + " themes.";
	private static final String ERROR_TOO_LONG = "That text is too long to be an exported theme.";
	private static final String ERROR_INVALID = "That doesn't look like a valid exported theme.";

	private final Supplier<String> themesReader;
	private final BiConsumer<String, String> configWriter;
	private final RightClickStylerConfig config;
	private final Gson gson;

	private final Map<String, Theme> userThemes = new LinkedHashMap<>();
	private String activeId = BuiltInThemes.DEFAULT_ID;
	private volatile Theme working = BuiltInThemes.find(BuiltInThemes.DEFAULT_ID);

	@Inject
	ThemeManager(ConfigManager configManager, RightClickStylerConfig config, Gson gson)
	{
		this(() -> configManager.getConfiguration(RightClickStylerConfig.GROUP,
			RightClickStylerConfig.KEY_USER_THEMES),
			(key, value) -> configManager.setConfiguration(RightClickStylerConfig.GROUP, key, value), config, gson);
	}

	ThemeManager(Supplier<String> themesReader, BiConsumer<String, String> configWriter,
		RightClickStylerConfig config, Gson gson)
	{
		this.themesReader = themesReader;
		this.configWriter = configWriter;
		this.config = config;
		this.gson = gson;
		reload();
	}

	Theme effectiveTheme()
	{
		return working;
	}

	void setWorking(Theme theme)
	{
		working = theme;
	}

	List<Theme> builtIns()
	{
		return BuiltInThemes.ALL;
	}

	List<Theme> userThemes()
	{
		return new ArrayList<>(userThemes.values());
	}

	String activeId()
	{
		return activeId;
	}

	Theme active()
	{
		Theme theme = find(activeId);
		return theme != null ? theme : BuiltInThemes.find(BuiltInThemes.DEFAULT_ID);
	}

	boolean isEdited()
	{
		return !working.sameStyle(active());
	}

	private boolean isFull()
	{
		return userThemes.size() >= Limits.MAX_USER_THEMES;
	}

	void applyTheme(String id)
	{
		Theme theme = find(id);
		if (theme == null)
		{
			return;
		}
		activeId = id;
		working = theme;
		persistActiveId();
	}

	void save()
	{
		Theme active = userThemes.get(activeId);
		if (active == null)
		{
			return;
		}
		Theme saved = working.withIdentity(active.id, active.name, false);
		userThemes.put(saved.id, saved);
		working = saved;
		persistUserThemes();
	}

	/**
	 * @return false if the user theme limit has been reached
	 */
	boolean saveAsNew(String name)
	{
		return addAndActivate(working, name);
	}

	void revert()
	{
		working = active();
	}

	void rename(String newName)
	{
		Theme active = userThemes.get(activeId);
		if (active == null)
		{
			return;
		}
		Theme renamed = active.withIdentity(active.id, cleanName(newName), false);
		userThemes.put(renamed.id, renamed);
		if (working.id.equals(active.id))
		{
			working = working.withIdentity(renamed.id, renamed.name, false);
		}
		persistUserThemes();
	}

	/**
	 * @return false if the user theme limit has been reached
	 */
	boolean duplicate()
	{
		Theme source = active();
		return addAndActivate(source, source.name + COPY_SUFFIX);
	}

	void delete(String id)
	{
		if (userThemes.remove(id) == null)
		{
			return;
		}
		persistUserThemes();
		if (activeId.equals(id))
		{
			applyTheme(BuiltInThemes.DEFAULT_ID);
		}
	}

	/**
	 * Exports the live working copy so sidebar edits are included without saving them.
	 */
	String exportWorking()
	{
		Theme theme = working;
		String json = gson.toJson(StoredTheme.from(theme));
		return EXPORT_PREFIX + Base64.getEncoder().encodeToString(json.getBytes(StandardCharsets.UTF_8));
	}

	/**
	 * Never throws.
	 *
	 * @return null on success, otherwise a message suitable for showing to the user
	 */
	String importTheme(String payload)
	{
		if (isFull())
		{
			return ERROR_FULL;
		}
		String trimmed = payload == null ? "" : payload.trim();
		if (trimmed.length() > Limits.MAX_IMPORT_LENGTH)
		{
			return ERROR_TOO_LONG;
		}
		if (trimmed.startsWith(EXPORT_PREFIX))
		{
			trimmed = trimmed.substring(EXPORT_PREFIX.length());
		}

		Theme theme;
		try
		{
			String json = new String(Base64.getDecoder().decode(trimmed), StandardCharsets.UTF_8);
			StoredTheme stored = gson.fromJson(json, StoredTheme.class);
			// an exported theme always carries an id; requiring one rejects arbitrary JSON objects
			theme = stored == null || stored.id == null || stored.id.isEmpty()
				? null : stored.toTheme(UUID.randomUUID().toString());
		}
		catch (RuntimeException e)
		{
			log.debug("Rejected theme import", e);
			return ERROR_INVALID;
		}
		if (theme == null)
		{
			return ERROR_INVALID;
		}

		addAndActivate(theme, theme.name);
		return null;
	}

	/**
	 * Replaces cached theme state from the active RuneLite configuration profile. This runs during
	 * construction and again after profile changes. Corrupt config loads as defaults rather than
	 * failing startup.
	 */
	void reload()
	{
		userThemes.clear();
		try
		{
			StoredTheme[] stored = gson.fromJson(themesReader.get(), StoredTheme[].class);
			if (stored != null)
			{
				for (StoredTheme s : stored)
				{
					if (userThemes.size() >= Limits.MAX_USER_THEMES)
					{
						break;
					}
					// first occurrence of a duplicated id wins
					if (s != null && isValidStoredId(s.id) && !userThemes.containsKey(s.id))
					{
						userThemes.put(s.id, s.toTheme(s.id));
					}
				}
			}
		}
		catch (RuntimeException e)
		{
			log.warn("Saved custom themes for Right Click Styler are corrupt; starting with none", e);
			userThemes.clear();
		}

		activeId = config.activeTheme();
		Theme theme = find(activeId);
		if (theme == null)
		{
			activeId = BuiltInThemes.DEFAULT_ID;
			theme = BuiltInThemes.find(activeId);
		}
		working = theme;
	}

	private static boolean isValidStoredId(String id)
	{
		return id != null && !id.isEmpty() && id.length() <= Limits.MAX_THEME_ID_LENGTH
			&& BuiltInThemes.find(id) == null;
	}

	private boolean addAndActivate(Theme source, String name)
	{
		if (isFull())
		{
			return false;
		}
		String id = UUID.randomUUID().toString();
		Theme theme = source.withIdentity(id, cleanName(name), false);
		userThemes.put(id, theme);
		activeId = id;
		working = theme;
		persistUserThemes();
		persistActiveId();
		return true;
	}

	private Theme find(String id)
	{
		if (id == null)
		{
			return null;
		}
		Theme builtIn = BuiltInThemes.find(id);
		return builtIn != null ? builtIn : userThemes.get(id);
	}

	private static String cleanName(String name)
	{
		String value = name == null ? "" : name;
		StringBuilder cleaned = null;
		for (int offset = 0; offset < value.length();)
		{
			int codePoint = value.codePointAt(offset);
			int width = Character.charCount(codePoint);
			if (Character.isISOControl(codePoint))
			{
				if (cleaned == null)
				{
					cleaned = new StringBuilder(value.length());
					cleaned.append(value, 0, offset);
				}
			}
			else if (cleaned != null)
			{
				cleaned.appendCodePoint(codePoint);
			}
			offset += width;
		}

		String trimmed = (cleaned == null ? value : cleaned.toString()).trim();
		return trimmed.isEmpty() ? DEFAULT_THEME_NAME : Limits.truncate(trimmed, Limits.MAX_THEME_NAME_LENGTH);
	}

	private void persistUserThemes()
	{
		List<StoredTheme> stored = new ArrayList<>(userThemes.size());
		for (Theme theme : userThemes.values())
		{
			stored.add(StoredTheme.from(theme));
		}
		configWriter.accept(RightClickStylerConfig.KEY_USER_THEMES, gson.toJson(stored));
	}

	private void persistActiveId()
	{
		configWriter.accept(RightClickStylerConfig.KEY_ACTIVE_THEME, activeId);
	}

	/**
	 * Gson-friendly shape for a theme: colours as plain ARGB ints, enums as names. Used for both the
	 * persisted user theme list and the clipboard export/import format. Boxed fields so that values
	 * missing from the JSON can be told apart and defaulted from the default built-in theme.
	 */
	private static final class StoredTheme
	{
		String id;
		String name;
		Integer bg;
		Integer border;
		Integer header;
		Integer headerText;
		Integer text;
		Integer hover;
		Integer accent;
		Integer radius;
		Integer opacity;
		String hoverStyle;
		Boolean showBorder;
		Boolean showShadow;
		Boolean showHeader;
		String font;
		Integer fontSize;
		Boolean textShadow;

		static StoredTheme from(Theme t)
		{
			StoredTheme s = new StoredTheme();
			s.id = t.id;
			s.name = t.name;
			s.bg = t.bg.getRGB();
			s.border = t.border.getRGB();
			s.header = t.header.getRGB();
			s.headerText = t.headerText.getRGB();
			s.text = t.text.getRGB();
			s.hover = t.hover.getRGB();
			s.accent = t.accent.getRGB();
			s.radius = t.radius;
			s.opacity = t.opacity;
			s.hoverStyle = t.hoverStyle.name();
			s.showBorder = t.showBorder;
			s.showShadow = t.showShadow;
			s.showHeader = t.showHeader;
			s.font = t.font.name();
			s.fontSize = t.fontSize;
			s.textShadow = t.textShadow;
			return s;
		}

		Theme toTheme(String themeId)
		{
			Theme d = BuiltInThemes.find(BuiltInThemes.DEFAULT_ID);
			return new Theme(themeId, cleanName(name), false,
				colour(bg, d.bg), colour(border, d.border), colour(header, d.header),
				colour(headerText, d.headerText), colour(text, d.text), colour(hover, d.hover),
				colour(accent, d.accent),
				Limits.clamp(radius != null ? radius : d.radius, Limits.MIN_RADIUS, Limits.MAX_RADIUS),
				Limits.clamp(opacity != null ? opacity : d.opacity, Limits.MIN_OPACITY, Limits.MAX_OPACITY),
				enumOr(HoverStyle.class, hoverStyle, d.hoverStyle),
				showBorder != null ? showBorder : d.showBorder,
				showShadow != null ? showShadow : d.showShadow,
				showHeader != null ? showHeader : d.showHeader,
				enumOr(FontChoice.class, font, d.font),
				Limits.clamp(fontSize != null ? fontSize : d.fontSize, Limits.MIN_FONT_SIZE, Limits.MAX_FONT_SIZE),
				textShadow != null ? textShadow : d.textShadow);
		}

		private static Color colour(Integer argb, Color fallback)
		{
			return argb != null ? new Color(argb, true) : fallback;
		}

		private static <E extends Enum<E>> E enumOr(Class<E> type, String name, E fallback)
		{
			if (name == null)
			{
				return fallback;
			}
			try
			{
				return Enum.valueOf(type, name);
			}
			catch (IllegalArgumentException e)
			{
				return fallback;
			}
		}
	}
}

package com.rightclickstyler;

import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Arrays;
import java.util.List;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/**
 * Draws a fixed sample menu with the current working theme, for live feedback while editing. Paints
 * on the EDT, so it never touches {@code Client}; player details come from {@link LocalPlayerSnapshot}.
 */
class ThemePreview extends JPanel
{
	private static final int TOP_MARGIN = 10;
	private static final int SIDE_MARGIN = 8;
	private static final int MIN_MENU_WIDTH = 10;
	// Lowest possible combat level; used while logged out.
	private static final int PLACEHOLDER_COMBAT_LEVEL = 3;

	private static final List<MenuRenderer.Row> SAMPLE_ROWS = Arrays.asList(
		new MenuRenderer.Row("Attack", "<col=ffff00>Guard</col> <col=ffffff>(level-21)</col>", MenuRenderer.TargetKind.NPC),
		new MenuRenderer.Row("Pickpocket", "<col=ffff00>Guard</col>", MenuRenderer.TargetKind.NPC),
		new MenuRenderer.Row("Use", "<col=ff9040>Lobster</col>", MenuRenderer.TargetKind.ITEM),
		new MenuRenderer.Row("Walk here", "", MenuRenderer.TargetKind.OTHER),
		new MenuRenderer.Row("Examine", "<col=ffff00>Guard</col>", MenuRenderer.TargetKind.NPC),
		new MenuRenderer.Row("Cancel", "", MenuRenderer.TargetKind.OTHER)
	);

	private final LocalPlayerSnapshot localPlayer;
	private final ThemeManager themeManager;
	private final RightClickStylerConfig config;
	private final MenuRenderer renderer = new MenuRenderer();
	private final Rectangle bounds = new Rectangle();

	private int hoverIndex = -1;

	ThemePreview(LocalPlayerSnapshot localPlayer, ThemeManager themeManager, RightClickStylerConfig config)
	{
		this.localPlayer = localPlayer;
		this.themeManager = themeManager;
		this.config = config;
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		localPlayer.setOnChange(this::repaint);

		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				updateHover(e.getY());
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				setHover(-1);
			}
		};
		addMouseMotionListener(mouse);
		addMouseListener(mouse);
	}

	/**
	 * Call after any change that can affect the drawn menu; header/row heights change its size.
	 */
	void refresh()
	{
		revalidate();
		repaint();
	}

	// DynamicGridLayout scales each child's preferred width to fill the column, so a width of 0 (as
	// getWidth() is before the first layout) would stay 0. Any non-zero width gets stretched to fit.
	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(MIN_MENU_WIDTH + SIDE_MARGIN * 2,
			rowsTop(themeManager.effectiveTheme()) + rowsHeight() + TOP_MARGIN);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		Theme theme = themeManager.effectiveTheme();
		int width = Math.max(MIN_MENU_WIDTH, getWidth() - SIDE_MARGIN * 2);
		// The renderer always leaves room for the header, so shift up when it's hidden.
		bounds.setBounds(SIDE_MARGIN, rowsTop(theme) - MenuRenderer.HEADER_HEIGHT, width,
			MenuRenderer.HEADER_HEIGHT + rowsHeight());
		int level = localPlayer.combatLevel();
		renderer.render((Graphics2D) g, null, theme, config, SAMPLE_ROWS, bounds, hoverIndex,
			level != LocalPlayerSnapshot.UNKNOWN ? level : PLACEHOLDER_COMBAT_LEVEL);
	}

	private void updateHover(int mouseY)
	{
		int relativeY = mouseY - rowsTop(themeManager.effectiveTheme());
		int index = relativeY < 0 ? -1 : relativeY / MenuRenderer.ROW_HEIGHT;
		setHover(index < SAMPLE_ROWS.size() ? index : -1);
	}

	private void setHover(int index)
	{
		if (index != hoverIndex)
		{
			hoverIndex = index;
			repaint();
		}
	}

	private static int rowsTop(Theme theme)
	{
		return TOP_MARGIN + (theme.showHeader ? MenuRenderer.HEADER_HEIGHT : 0);
	}

	private static int rowsHeight()
	{
		return MenuRenderer.ROW_HEIGHT * SAMPLE_ROWS.size();
	}
}

package com.rightclickstyler;

import java.awt.Rectangle;
import java.util.function.Consumer;
import net.runelite.api.Actor;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class MenuOverlayTest
{
	@Test
	public void usesCompleteNativeMenuBounds()
	{
		Rectangle bounds = new Rectangle();

		MenuOverlay.setNativeBounds(bounds, new StubMenu(12, 34, 207, 79));

		assertEquals(new Rectangle(12, 34, 207, 79), bounds);
	}

	@Test
	public void fallsBackBeforeInspectingScrollableMenus()
	{
		assertTrue(MenuOverlay.canInspectMenu(false, true, false));
		assertFalse(MenuOverlay.canInspectMenu(false, true, true));
		assertFalse(MenuOverlay.canInspectMenu(true, true, false));
		assertFalse(MenuOverlay.canInspectMenu(false, false, false));
	}

	@Test
	public void detectsSubmenus()
	{
		MenuEntry plain = new StubMenuEntry(MenuAction.CANCEL, -1, null);
		MenuEntry submenu = new StubMenuEntry(MenuAction.PLAYER_FIRST_OPTION, -1,
			new StubMenu(0, 0, 0, 0));

		assertFalse(MenuOverlay.containsSubMenu(new MenuEntry[]{plain}));
		assertTrue(MenuOverlay.containsSubMenu(new MenuEntry[]{plain, submenu}));
	}

	@Test
	public void classifiesEveryGameObjectActionBeforeItemIds()
	{
		MenuAction[] actions = {
			MenuAction.ITEM_USE_ON_GAME_OBJECT,
			MenuAction.WIDGET_TARGET_ON_GAME_OBJECT,
			MenuAction.GAME_OBJECT_FIRST_OPTION,
			MenuAction.GAME_OBJECT_SECOND_OPTION,
			MenuAction.GAME_OBJECT_THIRD_OPTION,
			MenuAction.GAME_OBJECT_FOURTH_OPTION,
			MenuAction.GAME_OBJECT_FIFTH_OPTION,
			MenuAction.EXAMINE_OBJECT
		};

		for (MenuAction action : actions)
		{
			MenuEntry entryWithItemId = new StubMenuEntry(action, 4151, null);
			assertEquals(action.name(), MenuRenderer.TargetKind.OBJECT, MenuOverlay.classify(entryWithItemId));
		}
	}

	private static final class StubMenu implements Menu
	{
		private final int x;
		private final int y;
		private final int width;
		private final int height;
		private MenuEntry[] entries = new MenuEntry[0];

		private StubMenu(int x, int y, int width, int height)
		{
			this.x = x;
			this.y = y;
			this.width = width;
			this.height = height;
		}

		@Override
		public MenuEntry createMenuEntry(int idx)
		{
			throw new UnsupportedOperationException();
		}

		@Override
		public MenuEntry[] getMenuEntries()
		{
			return entries;
		}

		@Override
		public void setMenuEntries(MenuEntry[] entries)
		{
			this.entries = entries;
		}

		@Override
		public void removeMenuEntry(MenuEntry entry)
		{
			throw new UnsupportedOperationException();
		}

		@Override
		public int getMenuX()
		{
			return x;
		}

		@Override
		public int getMenuY()
		{
			return y;
		}

		@Override
		public int getMenuWidth()
		{
			return width;
		}

		@Override
		public int getMenuHeight()
		{
			return height;
		}
	}

